//! Prospective high-throughput computational-execution assurance (`AFA-atlasx-P12-F27`).
//! The harness verifies a caller-supplied graph and never dispatches code or moves data.
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet, VecDeque};
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-atlasx-P12-F27";
pub const CONTRACT_VERSION: &str = "atlasx-prospective-computational-execution-assurance/1.0";
pub const INPUT_SCHEMA: &str = "ResearchWorkflowSpec3@1";
pub const OUTPUT_SCHEMA: &str = "ExecutionRun7@1";
pub const CONTENT_TYPE: &str = "application/vnd.aurora.atlasx-execution-run-7+json";
pub const PRECLINICAL_BOUNDARY: &str = "preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ExecutionEvidenceState { Proven, Supported, Unknown, Unmeasured, Contradicted, Negative }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutionNode3 { pub node_id:String, pub dependency_order:Vec<String>, pub effect_kind:String, pub evidence_state:ExecutionEvidenceState, pub artifact_digest:Option<ContentHash>, pub provenance_digest:Option<ContentHash>, pub replay_identity:ContentHash, pub estimated_cost:u32, pub omissions:Vec<String>, pub uncertainty:Vec<String>, pub policy_allowed:bool, pub protected_closure:bool }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ResearchWorkflowSpec3 { pub schema_version:String, pub request_id:String, pub run_id:String, pub workflow_id:String, pub scope:String, pub nodes:Vec<ExecutionNode3>, pub replay_identity:ContentHash, pub budget_units:u32, pub max_budget_units:u32, pub policy_allow:bool, pub protected_closure:bool, pub raw_data_local:bool, pub federated_summary_only:bool, pub adversarial_events:Vec<String>, pub boundary:String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutionArtifact7 { pub artifact_id:String, pub content_type:String, pub content_hash:ContentHash, pub semantic_loss:Vec<Value>, pub provenance:Vec<Value>, pub boundary:String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutionRun7 { pub schema_version:String, pub contract_version:String, pub feature_id:String, pub request_id:String, pub run_id:String, pub workflow_id:String, pub scope:String, pub disposition:String, pub plan_order:Vec<String>, pub topological_order:Vec<String>, pub completed_order:Vec<String>, pub unresolved_order:Vec<String>, pub blocked_order:Vec<String>, pub cycle_order:Vec<String>, pub missing_dependency_order:Vec<String>, pub compensation_order:Vec<String>, pub decisions:Vec<Value>, pub checkpoint_digest:ContentHash, pub replay_identity:ContentHash, pub run_digest:ContentHash, pub semantic_loss:Vec<Value>, pub omissions:Vec<String>, pub uncertainty:Vec<String>, pub negative_evidence:Vec<String>, pub artifact:ExecutionArtifact7, pub effect_receipts:Vec<String>, pub raw_data_local:bool, pub federation_export:String, pub boundary:String }
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum ComputationalExecutionError { #[error("invalid computational execution request: {0}")] Invalid(String), #[error("execution artifact failed: {0}")] Artifact(String) }
fn valid_hash(h:&ContentHash)->bool{h.as_str().len()==64&&h.as_str().bytes().all(|b|b.is_ascii_hexdigit())}
fn canonical(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
fn partition(u:&[String], parts:&[Vec<String>])->Result<(),ComputationalExecutionError>{let set=u.iter().cloned().collect::<BTreeSet<_>>();let flat=parts.iter().flatten().cloned().collect::<Vec<_>>();if set.len()!=u.len()||flat.len()!=set.len()||flat.iter().cloned().collect::<BTreeSet<_>>()!=set{return Err(ComputationalExecutionError::Invalid("execution states do not partition plan".into()))}Ok(())}
pub fn computational_execution_assurance_manifest()->Value{json!({"schema_version":"aurora-research-contract/1.0","capability_id":FEATURE_ID,"version":CONTRACT_VERSION,"owner_crate":"atlasx","consumers":["preclinical neuroscientist","computational execution operator","release evidence reviewer"],"behavior":"verify a prospective high-throughput research execution graph and emit replayable run evidence without dispatching code","value":"prevents cycles, missing dependencies, policy violations, budget overruns, and unreplayable plans from entering computation","input_schema":INPUT_SCHEMA,"output_schema":OUTPUT_SCHEMA,"effects":["block:unsafe-release"],"permissions":["evaluate:capability-runs"],"autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
fn validate_request(r:&ResearchWorkflowSpec3)->Result<(),ComputationalExecutionError>{if r.schema_version!=INPUT_SCHEMA||[&r.request_id,&r.run_id,&r.workflow_id,&r.scope].iter().any(|v|v.trim().is_empty())||r.nodes.is_empty()||r.budget_units==0||r.budget_units>r.max_budget_units||!valid_hash(&r.replay_identity)||!r.raw_data_local||!r.federated_summary_only||r.boundary!=PRECLINICAL_BOUNDARY||!canonical(&r.adversarial_events){return Err(ComputationalExecutionError::Invalid("execution identity, bounds, locality, replay, or boundary is invalid".into()))}let mut ids=BTreeSet::new();for n in &r.nodes{if n.node_id.trim().is_empty()||!ids.insert(n.node_id.clone())||!canonical(&n.dependency_order)||!canonical(&n.omissions)||!canonical(&n.uncertainty)||!valid_hash(&n.replay_identity)||n.artifact_digest.as_ref().is_some_and(|h|!valid_hash(h))||n.provenance_digest.as_ref().is_some_and(|h|!valid_hash(h)){return Err(ComputationalExecutionError::Invalid("node identifiers, dependencies, evidence, or digests are invalid".into()))}}Ok(())}
impl ExecutionRun7{pub fn validate(&self)->Result<(),ComputationalExecutionError>{if self.schema_version!="aurora-research-contract/1.0"||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||self.artifact.content_type!=CONTENT_TYPE||self.federation_export!="aggregate-digest-only"||!self.raw_data_local||self.plan_order.is_empty()||self.decisions.len()!=self.plan_order.len()||self.effect_receipts.is_empty()||!["qualified","unresolved","blocked"].contains(&self.disposition.as_str()){return Err(ComputationalExecutionError::Invalid("execution identity, locality, plan, decisions, or effects are incomplete".into()))}for v in [&self.plan_order,&self.topological_order,&self.completed_order,&self.unresolved_order,&self.blocked_order,&self.cycle_order,&self.missing_dependency_order,&self.compensation_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !canonical(v){return Err(ComputationalExecutionError::Invalid("execution ordering is not canonical".into()))}}partition(&self.plan_order,&[self.completed_order.clone(),self.unresolved_order.clone(),self.blocked_order.clone()])?;if !valid_hash(&self.checkpoint_digest)||!valid_hash(&self.replay_identity)||!valid_hash(&self.run_digest)||self.artifact.content_hash!=self.run_digest||self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("verify:execution-plan:")){return Err(ComputationalExecutionError::Invalid("execution digest or effect gate is invalid".into()))}Ok(())}pub fn digest(&self)->Result<ContentHash,ComputationalExecutionError>{self.validate()?;ContentHash::of_value(&serde_json::to_value(self).map_err(|e|ComputationalExecutionError::Artifact(e.to_string()))?).map_err(|e|ComputationalExecutionError::Artifact(e.to_string()))}}
pub fn assure_computational_execution(r:&ResearchWorkflowSpec3)->Result<ExecutionRun7,ComputationalExecutionError>{validate_request(r)?;let mut nodes=r.nodes.clone();nodes.sort_by(|a,b|a.node_id.cmp(&b.node_id));let plan=nodes.iter().map(|n|n.node_id.clone()).collect::<Vec<_>>();let set=plan.iter().cloned().collect::<BTreeSet<_>>();let mut indegree=nodes.iter().map(|n|(n.node_id.clone(),n.dependency_order.iter().filter(|d|set.contains(*d)).count())).collect::<BTreeMap<_,_>>();let mut children:BTreeMap<String,Vec<String>>=BTreeMap::new();for n in &nodes{for d in &n.dependency_order{if set.contains(d){children.entry(d.clone()).or_default().push(n.node_id.clone());}}}let mut q=VecDeque::from_iter(plan.iter().filter(|id|indegree[*id]==0).cloned());let mut topo=Vec::new();while let Some(id)=q.pop_front(){topo.push(id.clone());for child in children.get(&id).into_iter().flatten(){let x=indegree.get_mut(child).unwrap();*x-=1;if *x==0{q.push_back(child.clone());}}}let topo_set=topo.iter().cloned().collect::<BTreeSet<_>>();let cycle=plan.iter().filter(|id|!topo_set.contains(*id)).cloned().collect::<Vec<_>>();let mut completed=Vec::new();let mut unresolved=Vec::new();let mut blocked=Vec::new();let mut missing=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut decisions=Vec::new();let mut semantic_loss=Vec::new();let mut spent=0u32;let global_block=!r.policy_allow||!r.protected_closure||!r.raw_data_local||!r.federated_summary_only||!r.adversarial_events.is_empty();for n in &nodes{let id=n.node_id.clone();for d in &n.dependency_order{if !set.contains(d){missing.insert(format!("{id}:{d}"));omissions.insert(format!("{id}:missing-dependency:{d}"));}}omissions.extend(n.omissions.iter().map(|x|format!("{id}:{x}")));uncertainty.extend(n.uncertainty.iter().map(|x|format!("{id}:{x}")));if n.evidence_state==ExecutionEvidenceState::Negative{negative.insert(format!("{id}:negative-result"));}let failed=global_block||!n.policy_allowed||!n.protected_closure||n.artifact_digest.is_none()||n.provenance_digest.is_none()||cycle.contains(&id)||n.replay_identity!=r.replay_identity;let mut pending=!failed&&(matches!(n.evidence_state,ExecutionEvidenceState::Unknown|ExecutionEvidenceState::Unmeasured|ExecutionEvidenceState::Contradicted)||!n.omissions.is_empty()||!n.uncertainty.is_empty()||n.dependency_order.iter().any(|d|!set.contains(d))||n.dependency_order.iter().any(|d|!completed.contains(d)));if n.estimated_cost>r.budget_units.saturating_sub(spent){pending=true;omissions.insert(format!("{id}:budget-ceiling"));}else{spent=spent.saturating_add(n.estimated_cost);}let disposition=if failed{"blocked"}else if pending{"unresolved"}else{"completed"};match disposition{"blocked"=>blocked.push(id.clone()),"unresolved"=>unresolved.push(id.clone()),_=>completed.push(id.clone())};if failed{semantic_loss.push(json!({"field":format!("node:{id}"),"reason":"execution gate failed","severity":"decision_relevant"}));}decisions.push(json!({"node_id":id,"effect_kind":n.effect_kind,"disposition":disposition}));}if global_block{completed.clear();unresolved.clear();blocked=plan.clone();omissions.insert("request:policy-or-locality-blocked".into());}completed.sort();unresolved.sort();blocked.sort();let disposition=if global_block||!blocked.is_empty(){"blocked"}else if !unresolved.is_empty()||completed.len()!=plan.len(){"unresolved"}else{"qualified"};if disposition!="qualified"{omissions.insert("request:execution-closure-not-ready".into());}let checkpoint=ContentHash::of_value(&json!({"run_id":r.run_id,"plan_order":plan,"topological_order":topo,"replay_identity":r.replay_identity})).map_err(|e|ComputationalExecutionError::Artifact(e.to_string()))?;let mut payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":r.request_id,"run_id":r.run_id,"workflow_id":r.workflow_id,"scope":r.scope,"disposition":disposition,"plan_order":plan,"topological_order":topo,"completed_order":completed,"unresolved_order":unresolved,"blocked_order":blocked,"cycle_order":cycle,"missing_dependency_order":missing.into_iter().collect::<Vec<_>>(),"compensation_order":Vec::<String>::new(),"decisions":decisions,"checkpoint_digest":checkpoint,"replay_identity":r.replay_identity,"semantic_loss":semantic_loss,"omissions":omissions.into_iter().collect::<Vec<_>>(),"uncertainty":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence":negative.into_iter().collect::<Vec<_>>(),"raw_data_local":true,"federation_export":"aggregate-digest-only","boundary":PRECLINICAL_BOUNDARY});let run_digest=ContentHash::of_value(&payload).map_err(|e|ComputationalExecutionError::Artifact(e.to_string()))?;payload["run_digest"]=json!(run_digest);payload["artifact"]=json!({"artifact_id":format!("execution-run-7:{}",r.run_id),"content_type":CONTENT_TYPE,"content_hash":run_digest,"semantic_loss":payload["semantic_loss"],"provenance":[{"source_id":r.run_id,"relation":"computational-execution-assurance","digest":run_digest}],"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("verify:execution-plan:{}",r.run_id)]}else{vec!["block:unsafe-release".to_string()]});let out:ExecutionRun7=serde_json::from_value(payload).map_err(|e|ComputationalExecutionError::Artifact(e.to_string()))?;out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(s:&str)->ContentHash{ContentHash::of_bytes(s.as_bytes())}fn node(id:&str,dep:Vec<String>)->ExecutionNode3{ExecutionNode3{node_id:id.into(),dependency_order:dep,effect_kind:"compute-local".into(),evidence_state:ExecutionEvidenceState::Supported,artifact_digest:Some(h("a")),provenance_digest:Some(h("p")),replay_identity:h("r"),estimated_cost:1,omissions:vec![],uncertainty:vec![],policy_allowed:true,protected_closure:true}}fn req(nodes:Vec<ExecutionNode3>)->ResearchWorkflowSpec3{ResearchWorkflowSpec3{schema_version:INPUT_SCHEMA.into(),request_id:"req".into(),run_id:"run".into(),workflow_id:"wf".into(),scope:"preclinical".into(),nodes,replay_identity:h("r"),budget_units:4,max_budget_units:4,policy_allow:true,protected_closure:true,raw_data_local:true,federated_summary_only:true,adversarial_events:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(assure_computational_execution(&req(vec![node("a",vec![]),node("b",vec!["a".into()])])).unwrap().disposition,"qualified")}#[test]fn cycle_is_blocked(){let o=assure_computational_execution(&req(vec![node("a",vec!["b".into()]),node("b",vec!["a".into()])])).unwrap();assert_eq!(o.disposition,"blocked")}#[test]fn policy_is_explicit(){let mut r=req(vec![node("a",vec![])]);r.policy_allow=false;assert_eq!(assure_computational_execution(&r).unwrap().effect_receipts,vec!["block:unsafe-release"])} }
